INSERT INTO questions (
    external_id, subject, topic, subtopic,
    fact_pattern, question_stem, call_of_question,
    difficulty, status, source_type, version, metadata
) VALUES (
    '22287_padilla-plea', 'CRIMINAL', 'Constitutional Protection of Accused Persons (Criminal Procedure)', 'Right to Counsel',
    'Timothy had lived in the United States since childhood, when his family immigrated from overseas when he was eight years old. He was never naturalized. Decades later, Timothy was arrested in a federal sting operation and charged with distributing a controlled substance. The evidence against him was overwhelming. His defense attorney urged him to accept a plea deal that would reduce his prison time. Timothy was terrified of being deported and asked his attorney directly whether a guilty plea could lead to removal. His attorney confidently told him it could not. Relying on that assurance, Timothy pleaded guilty. The conviction turned out to be for an aggravated felony, which carried mandatory deportation. Timothy moved to vacate his conviction, claiming ineffective assistance of counsel.', 'Timothy had lived in the United States since childhood, when his family immigrated from overseas when he was eight years old. He was never naturalized. Decades later, Timothy was arrested in a federal sting operation and charged with distributing a controlled substance. The evidence against him was overwhelming. His defense attorney urged him to accept a plea deal that would reduce his prison time. Timothy was terrified of being deported and asked his attorney directly whether a guilty plea could lead to removal. His attorney confidently told him it could not. Relying on that assurance, Timothy pleaded guilty. The conviction turned out to be for an aggravated felony, which carried mandatory deportation. Timothy moved to vacate his conviction, claiming ineffective assistance of counsel.', 'Is Timothy likely to prevail on his ineffective assistance of counsel claim?',
    NULL, 'draft', 'c3_transformed', 1, '{"source_qid": "22287_padilla-plea", "schema_variant": "transformed_v1", "outline_code": "75090400", "transformed": true, "c3_confidence": null, "c3_verdict": null}'
